       "why": "Reference: IFRS 15 Revenue from Contracts with Customers. Rule: a right of return makes consideration variable. Applied: 95 × $500 = $47,500 revenue; refund liability 5 × $500 = $2,500; asset 5 × $200 = $1,000, credited to cost of sales. Common mistake: recording the full $50,000, or measuring the liability at cost."
