     "id": "sbr-05-5",
     "track": "know",
     "name": "5.5 IAS 38 Intangible assets",
     "about": "Definition, recognition, models, R&D",
     "items": [
      {
       "key": "An intangible asset is an identifiable, non-monetary asset …",
       "text": "without physical substance",
       "image": "a glowing logo you can't touch",
       "why": "Reference: IAS 38 Intangible Assets. E.g. software, patents, licences, customer lists, franchises."
      },
      {
       "key": "Identifiable means separable, or …",
       "text": "arising from contractual or legal rights",
       "image": "a patent with a cut-out line",
       "why": "Reference: IAS 38 Intangible Assets. Goodwill isn't identifiable, which is why it's dealt with in IFRS 3."
      },
      {
       "key": "Intangibles are recognised if identifiable, controlled, bringing future benefits and …",
       "text": "measurable reliably",
       "image": "four ticks on a glowing logo",
       "why": "Reference: IAS 38 Intangible Assets. Costs already expensed can never be capitalised later."
      },
      {
       "key": "An internally generated brand is not recognised because …",
       "text": "its costs can't be separated from running the business",
       "image": "a homemade brand banner",
       "why": "Reference: IAS 38 Intangible Assets. Innovate example: the 'Our Sports' brand stays off; the bought 'Pets & Me' rights go on at $1m."
      },
      {
       "key": "Intangibles can be revalued only if there is …",
       "text": "an active market (homogeneous, always buyers and sellers, public prices)",
       "image": "a milk quota auction",
       "why": "Reference: IAS 38 Intangible Assets. Rare: milk quotas or exchange seats, never brands or patents."
      },
      {
       "key": "A finite-life intangible is amortised, usually straight-line with …",
       "text": "zero residual value, from when it's available for use",
       "image": "a melting logo",
       "why": "Reference: IAS 38 Intangible Assets. An indefinite life means no foreseeable limit to cash inflows."
      },
      {
       "key": "An indefinite-life intangible is …",
       "text": "not amortised but tested for impairment every year",
       "image": "a logo with an annual X-ray",
       "why": "Reference: IAS 38 Intangible Assets. JonJon: saying 'we can't foresee its life' because of change doesn't make a customer list indefinite."
      },
      {
       "key": "Research spending is always …",
       "text": "expensed",
       "image": "a lab notebook in the bin",
       "why": "Reference: IAS 38 Intangible Assets. Tangible assets used in research are still PPE."
      },
      {
       "key": "Development is capitalised once the entity shows technical feasibility, intention to complete, future benefits, resources and …",
       "text": "reliable measurement of the costs",
       "image": "a prototype in a vault",
       "why": "Reference: IAS 38 Intangible Assets. Scone: only development after 1 May (when profitability was shown) is capitalised; market research and training are expensed."
      },
      {
       "key": "IAS 38 requires disclosure of R&D expensed, amortisation methods, revaluations, a reconciliation and …",
       "text": "the reasons for any indefinite-life assessment",
       "image": "a note explaining 'forever'",
       "why": "Reference: IAS 38 Intangible Assets. Users can challenge indefinite lives."
      }
     ]
