       "a": 0,
       "why": "Reference: IFRS 5 Non-current Assets Held for Sale and Discontinued Operations. Rule: revalue to fair value first, as IAS 16 would, then charge the costs to sell to P/L. Applied: 1.95 → 1.85 against the surplus; then 0.1 in P/L, leaving 1.75. Common mistake: taking the whole drop to one place."
