       "key": "Monetary items are rights or obligations to receive or pay …",
       "text": "a fixed or determinable number of currency units",
       "image": "coins and IOUs",
       "why": "Reference: IAS 21 The Effects of Changes in Foreign Exchange Rates. Cash, receivables, payables and loans are monetary. PPE, inventory, intangibles and prepayments for goods are not."
