       "why": "Reference: IFRS 16 Leases. Rule: a change in an index means recalculating the liability, against the right-of-use asset, at the original rate. Applied: 2.2 + 2.2/1.05 = 4.295; 4.295 − 3.905 = 0.39. Common mistake: taking it to P/L, or revising the rate."
