     "id": "sbr-09-watch-1",
     "track": "watch",
     "name": "9.W Pension traps",
     "about": "True or false, and why",
     "items": [
      {
       "t": "tf",
       "q": "A defined benefit obligation is measured at present value.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits. Plan assets are at fair value."
      },
      {
       "t": "tf",
       "q": "Benefits paid to pensioners change the net deficit.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. Assets and obligation fall by the same amount."
      },
      {
       "t": "tf",
       "q": "Contributions reduce the expense in profit or loss.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. They only move the net balance."
      },
      {
       "t": "tf",
       "q": "Net interest uses the discount rate at the start of the year.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits. Applied to the opening net figure."
      },
      {
       "t": "tf",
       "q": "Past service costs wait until the benefits vest.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. Vesting isn't relevant: recognise them at the earlier of the event and any related restructuring or termination costs."
      },
      {
       "t": "tf",
       "q": "A remeasurement loss can be spread over employees' remaining working lives.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. It goes to OCI in full, immediately."
      },
      {
       "t": "tf",
       "q": "The remeasurement component can be recycled to P/L later.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. There's no clear basis for the amount or timing."
      },
      {
       "t": "tf",
       "q": "A surplus is limited to refunds and reductions in future contributions.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits. The asset ceiling."
      },
      {
       "t": "tf",
       "q": "A plan the company could legally cancel can still be defined benefit.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits. If past practice creates a valid expectation."
      },
      {
       "t": "tf",
       "q": "Using an actuary removes all uncertainty in pension figures.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. It reduces bias, but the assumptions can still change a lot."
      },
      {
       "t": "tf",
       "q": "Sensitivity analysis on pension assumptions must be disclosed.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits. Investors can see the exposure."
      },
      {
       "t": "tf",
       "q": "An unused non-accumulating absence creates a liability.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. It's only recognised when the absence occurs."
      },
      {
       "t": "tf",
       "q": "Reflecting future salary rises seems to conflict with the Framework's liability definition.",
       "a": true,
       "why": "Reference: IAS 19 Employee Benefits; Conceptual Framework. A stated criticism: there's no current obligation to pay them."
      },
      {
       "t": "tf",
       "q": "Long-service award remeasurements go to OCI.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits. They go to P/L."
      },
      {
       "t": "tf",
       "q": "Termination benefits are recognised when the employees actually leave.",
       "a": false,
       "why": "Reference: IAS 19 Employee Benefits; IAS 37 Provisions, Contingent Liabilities and Contingent Assets. At the earlier of when the offer can't be withdrawn and when IAS 37 restructuring costs are recognised."
      }
     ]
