       "why": "Reference: IFRS 9 Financial Instruments. Step 1 (model): collect and sell means FVOCI. Step 2 (interest): 49,000 × 7% = 3,430 to P/L. Step 3 (amortised cost): 49,000 + 3,430 − 2,000 = 50,430. Step 4 (fair value): 52,000 − 50,430 = 1,570 to OCI. P/L category: Investing. Common mistake: taking the coupon as income."
