     "name": "18.S3 The workings as a map",
     "about": "What goes in each working",
     "items": [
      {
       "t": "order",
       "q": "The five workings for a group statement of financial position",
       "steps": [
        "W1 Group structure: who is a subsidiary, associate, joint venture",
        "W2 Subsidiary's net assets at acquisition and at the reporting date",
        "W3 Goodwill",
        "W4 Non-controlling interest",
        "W5 Group reserves"
       ],
       "why": "Reference: IFRS 10 Consolidated Financial Statements; IFRS 3 Business Combinations. Every correction lands in one of these; knowing the map tells you which figures move."
      },
      {
       "t": "order",
       "q": "Building W2 for a subsidiary",
       "steps": [
        "Share capital and reserves (at acquisition and at the reporting date)",
        "Remove any goodwill in the subsidiary's own books",
        "Add fair value adjustments",
        "Deduct extra depreciation on them since acquisition",
        "Deduct PURP where the subsidiary is the seller"
       ],
       "why": "Reference: IFRS 10 Consolidated Financial Statements; IFRS 3 Business Combinations. The movement between the two columns is the post-acquisition profit shared with the NCI."
      },
      {
       "t": "order",
       "q": "Goodwill (W3)",
       "steps": [
        "Fair value of consideration",
        "Add NCI at acquisition (fair value or share of net assets)",
        "Deduct fair value of identifiable net assets at acquisition (W2)",
        "Deduct impairment to date"
       ],
       "why": "Reference: IFRS 3 Business Combinations; IFRS 10 Consolidated Financial Statements. A negative figure is a bargain purchase: re-check the numbers, then a gain in P/L."
      },
      {
       "t": "order",
       "q": "Group retained earnings (W5)",
       "steps": [
        "Parent's retained earnings",
        "Add group share of the subsidiary's post-acquisition reserves (W2)",
        "Add group share of associates' post-acquisition reserves",
        "Deduct group share of goodwill impairment",
        "Deduct PURP where the parent is the seller and other parent-level adjustments"
       ],
       "why": "Reference: IFRS 10 Consolidated Financial Statements. Parent-level corrections (fees, unwinding, parent's PURP) hit here only."
      },
      {
       "t": "order",
       "q": "Non-controlling interest (W4)",
       "steps": [
        "NCI at acquisition (as in W3)",
        "Add NCI share of post-acquisition change in net assets (W2)",
        "Deduct NCI share of goodwill impairment (fair value method only)"
       ],
       "why": "Reference: IFRS 10 Consolidated Financial Statements. So any adjustment inside W2 changes the NCI."
      }
     ]
