       "why": "Reference: IFRS 3 Business Combinations; IFRS 10 Consolidated Financial Statements. Rule: a bargain purchase is rare; IFRS 3 asks you to review every figure, then recognise the gain in P/L. Applied: 400 + 100 − 560 = −60. P/L category: A bargain purchase gain in P/L (Operating). Users: A one-off gain flatters profit; users should strip it out when judging sustainable earnings. Common mistake: carrying negative goodwill on the balance sheet."
