     "id": "sbr-19-apply-1",
     "track": "apply",
     "name": "19.A1 Gaining control",
     "about": "Work out the treatment",
     "items": [
      {
       "t": "case",
       "q": "Owl buys 75% of Robin on 1 April; the year ends 31 December. Robin earns 400 evenly over the year. A fair value uplift of 800 is depreciated over 4 years; goodwill (NCI at fair value) is impaired by 50 this year. What profit goes to the NCI?",
       "opts": [
        "25",
        "37.5",
        "75",
        "100"
       ],
       "a": 0,
       "why": "Reference: IFRS 10 Consolidated Financial Statements; IFRS 3 Business Combinations. Rule: consolidate from the control date; the NCI shares post-acquisition profit after fair value depreciation and, with full goodwill, impairment. Applied: 400 × 9/12 = 300; depreciation 800 / 4 × 9/12 = 150; 300 − 150 − 50 = 100; 25% = 25. P/L category: Robin's results in their usual categories (mostly Operating); impairment and extra depreciation in Operating. Users: Only nine months of Robin's revenue and profit, so growth looks bigger next year when a full year is included. Common mistakes: 37.5 (forgetting impairment), 75 (no adjustments), 100 (whole year)."
      },
      {
       "t": "case",
       "q": "Hawk holds 15% of Wren (FVTPL, carried at 30). It buys a further 45% for 120, gaining control. At that date the 15% is worth 36, the 40% NCI's fair value is 95 and Wren's net assets are 200. Treatment?",
       "opts": [
        "Gain 6 in P/L; goodwill 51",
        "No gain; goodwill 45",
        "Gain 6 in P/L; goodwill 15",
        "Gain 6 in OCI; goodwill 51"
       ],
       "a": 0,
       "why": "Reference: IFRS 3 Business Combinations; IFRS 9 Financial Instruments. Rule: remeasure the old holding at the control date, gain to P/L, and use its fair value in goodwill. Applied: 36 − 30 = 6 (investing); goodwill 36 + 120 + 95 − 200 = 51. P/L category: Gain of 6 in Investing. Users: A one-off remeasurement gain: users should exclude it from sustainable profit. Common mistakes: 45 (using the carrying amount 30), 15 (leaving the old holding out)."
      },
      {
       "t": "case",
       "q": "Kite has held 30% of Lark as an associate, carried at 84. It buys another 30% for 100, gaining control. The old 30% is then worth 90; NCI is measured at its 40% share of net assets of 250. What is the gain and the goodwill?",
       "opts": [
        "Gain 6; goodwill 40",
        "No gain; goodwill 34",
        "Gain 6; goodwill 140",
        "Gain 90; goodwill 40"
       ],
       "a": 0,
       "why": "Reference: IAS 28 Investments in Associates and Joint Ventures; IFRS 9 Financial Instruments. Rule: an associate stake is remeasured to fair value when control is gained, and that fair value goes into goodwill. Applied: gain 90 − 84 = 6 (investing); goodwill 90 + 100 + 100 (40% × 250) − 250 = 40. P/L category: Gain of 6 in Investing; from then on Lark is consolidated line by line. Users: The group's revenue, assets and debt jump as Lark moves from one line to full consolidation. Common mistakes: 34 (using 84), 140 (forgetting to deduct net assets)."
      },
      {
       "t": "case",
       "q": "Hawk held 15% of Wren, designated at fair value through OCI and carried at 30. It buys a further 45%, gaining control, when the 15% is worth 36. Where does the 6 remeasurement gain go?",
       "opts": [
        "OCI, and it is never recycled to P/L",
        "P/L (investing)",
        "Goodwill",
        "OCI, recycled to P/L when control is gained"
       ],
       "a": 0,
       "why": "Reference: IFRS 3 Business Combinations; IFRS 9 Financial Instruments. Rule: equity investments designated FVOCI keep their gains in OCI permanently. Applied: the 6 goes to OCI; goodwill still uses the fair value of 36. P/L category: OCI, not recycled. Users: No effect on EPS; total comprehensive income shows the gain. Common mistake: recycling it on the change of status."
      }
     ]
