       "a": 0,
       "why": "Reference: IFRS 10 Consolidated Financial Statements. Rule: losing control means remeasuring the stake kept to fair value and recognising a gain in P/L. Applied: 300 + 160 − (500 + 90 − 140) = 10; the 25% is equity-accounted from a cost of 160. P/L category: Gain of 10 in Operating; later share of Moose's profit in Investing. Users: Revenue and debt fall as Moose leaves the group; gearing may improve. Common mistake: keeping it at its share of the old net assets."
