     "id": "sbr-22-watch-1",
     "track": "watch",
     "name": "22.W1 Ratios, EPS and APMs",
     "about": "True or false, and why",
     "items": [
      {
       "t": "tf",
       "q": "SBR places less emphasis on calculating ratios than Financial Reporting does.",
       "a": true,
       "why": "Reference: Kaplan, analysis and interpretation. Explain what the figures mean; the calculations are a tool."
      },
      {
       "t": "tf",
       "q": "A private company that chooses to disclose EPS must calculate it under IAS 33.",
       "a": true,
       "why": "Reference: IAS 33 Earnings per Share. IAS 33 applies to listed entities and to anyone choosing to disclose EPS."
      },
      {
       "t": "tf",
       "q": "A bonus issue raises EPS because share capital goes up.",
       "a": false,
       "why": "Reference: IAS 33 Earnings per Share. No cash comes in and earnings don't change, so more shares means lower EPS."
      },
      {
       "t": "tf",
       "q": "A share issue at full price means the comparative EPS must be restated.",
       "a": false,
       "why": "Reference: IAS 33 Earnings per Share. Only bonus elements restate comparatives; a full-price issue is just time-weighted."
      },
      {
       "t": "tf",
       "q": "A rights issue below market price has a bonus element.",
       "a": true,
       "why": "Reference: IAS 33 Earnings per Share. So a bonus fraction applies to the shares before the issue."
      },
      {
       "t": "tf",
       "q": "Operating profit can replace profit before financing and income taxes in ROCE only if there is no investment income.",
       "a": true,
       "why": "Reference: Kaplan, analysis and interpretation. With no investment income the two figures are the same."
      },
      {
       "t": "tf",
       "q": "A long payables period is always a bad sign.",
       "a": false,
       "why": "Reference: Kaplan, analysis and interpretation. It's free finance, though taking too long can mean credit being reduced or withdrawn."
      },
      {
       "t": "tf",
       "q": "An upward revaluation can make ROCE worse and gearing better at once.",
       "a": true,
       "why": "Reference: IAS 16 Property, Plant and Equipment. Higher depreciation cuts profit and higher equity raises capital employed, while gearing falls."
      },
      {
       "t": "tf",
       "q": "Accounting policy choices change the ratios and also change cash generation.",
       "a": false,
       "why": "Reference: Kaplan, analysis and interpretation. Choices and estimates alter the picture, not the cash."
      },
      {
       "t": "tf",
       "q": "Depreciation is safe to add back in an APM because it is non-cash.",
       "a": false,
       "why": "Reference: Kaplan, analysis and interpretation. The assets still have to be replaced, so it's a real cost over time."
      },
      {
       "t": "tf",
       "q": "Excluding an impairment from an APM can hide a poor past decision.",
       "a": true,
       "why": "Reference: Kaplan, analysis and interpretation. An impairment may show management overpaid or that prospects are weaker."
      },
      {
       "t": "tf",
       "q": "Gains on financial assets at FVPL are always one-off.",
       "a": false,
       "why": "Reference: Kaplan, analysis and interpretation. Entities trading such assets repeat them, so excluding them isn't automatically right."
      }
     ]
